+import { EventEmitter } from 'events';
+import { describe, expect, it, vi } from 'vitest';
+import { createDesktopConsultRunner } from '../../../main/cross-agent/consult-runner';
+import type { ProcessManager } from '../../../main/process-manager';
+import type { ConsultObserver } from '../../../shared/maestro-lib/agents/consult';
+import type { GroupChatSpawn } from '../../../shared/maestro-lib/groupchat/types';
+
+vi.mock('../../../main/group-chat/spawnGroupChatAgent', () => ({
+	spawnGroupChatAgent: async () => ({ success: true, pid: 123 }),
+}));
+vi.mock('../../../main/group-chat/spawn-config', () => ({
+	toSpawnGroupChatAgentConfig: () => ({}),
+}));
+
+describe('desktop consult failure forwarding', () => {
+	it('delivers the own process auth error and releases all listeners at exit', async () => {
+		const emitter = new EventEmitter();
+		const runner = createDesktopConsultRunner(emitter as ProcessManager, null);
+		const onEnd = vi.fn();
+		await runner.start({ processId: 'cross-agent-auth', providerId: 'codex' } as GroupChatSpawn, {
+			onActivity: vi.fn(),
+			onSessionId: vi.fn(),
+			onEnd,
+		} satisfies ConsultObserver);
+		emitter.emit('agent-error', 'unrelated', { message: 'ignore' });
+		emitter.emit('agent-error', 'cross-agent-auth', {
+			message: 'Authentication or MCP may be blocked',
+		});
+		emitter.emit('exit', 'cross-agent-auth', 1);
+		expect(onEnd).toHaveBeenCalledExactlyOnceWith(
+			expect.objectContaining({ exitCode: 1, error: 'Authentication or MCP may be blocked' })
+		);
+		expect(emitter.eventNames()).toEqual([]);
+	});
+});
diff --git a/src/__tests__/main/process-manager/spawners/ChildProcessSpawner.auth-lifecycle.test.ts b/src/__tests__/main/process-manager/spawners/ChildProcessSpawner.auth-lifecycle.test.ts
