+export function superviseAgentProcess(
+	child: ChildProcess,
+	options: {
+		timeoutMs?: number;
+		idle?: HeadlessIdleProfile;
+		usageReporting?: UsageReporting;
+		onStatus?: (text: string) => void;
+		startupMs?: number;
+		signal?: AbortSignal;
+		onStop: (reason: string) => void;
+		onForcedStop: () => void;
+	}
