+			onIdle: () =>
+				stop(
+					`Codex produced no model activity within ${options.startupMs! / 1000} seconds. Startup or authentication may be blocked, for example by an interactive keyring prompt. Check Codex login and the credential store on the agent host; after fixing them, retry the request. For a host already using file credentials, verify both cli_auth_credentials_store=file and mcp_oauth_credentials_store=file in the agent's effective Codex configuration.`
+				),
+		});
+	}
+	if (options.timeoutMs) {
+		lifetime = createIdleWatchdog({
+			idleMs: options.timeoutMs,
+			onIdle: () => stop('Agent run stopped: absolute runtime ceiling exceeded'),
+		});
+	}
+	const onExit = (): void => {
+		if (disposed || stopping) return;
+		exitDrain = createIdleWatchdog({
+			idleMs: HEADLESS_PROCESS_CLOSE_TIMEOUT_MS,
+			onIdle: () => {
+				stop('Agent run stopped: provider exited without closing output streams');
+				forceStop();
+			},
+		});
+	};
+	child.once?.('exit', onExit);
+	armWarning();
+	armSilence();
+	options.signal?.addEventListener('abort', abort, { once: true });
+	if (options.signal?.aborted) abort();
+	return {
+		modelActivity: () => {
+			if (!disposed && !stopping) startup?.disarm();
+		},
+		observe,
+		dispose: () => {
+			if (disposed) return;
+			disposed = true;
+			startup?.disarm();
+			lifetime?.disarm();
+			silence?.disarm();
+			warning?.disarm();
+			exitDrain?.disarm();
+			child.removeListener?.('exit', onExit);
+			if (closeDeadline) clearTimeout(closeDeadline);
+			options.signal?.removeEventListener('abort', abort);
+			termination?.dispose();
+		},
+	};
+}
